#!/bin/bash

# This testbench is generated by deepseek.

set -e  # 任何命令出错时退出

DB_FILE="test.db"

echo "=== 数据库测试脚本 ==="

# 清理之前的测试文件
rm -f $DB_FILE

echo "1. 创建新数据库"
./ex17 $DB_FILE c

echo "2. 设置记录 0: Alice"
./ex17 $DB_FILE s 0 "Alice" "alice@example.com"

echo "3. 设置记录 1: Bob"
./ex17 $DB_FILE s 1 "Bob" "bob@example.com"

echo "4. 设置记录 2: Charlie"
./ex17 $DB_FILE s 2 "Charlie" "charlie@example.com"

echo "5. 获取记录 1"
./ex17 $DB_FILE g 1

echo "6. 列出所有记录"
./ex17 $DB_FILE l

echo "7. 查找包含 'alice' 的记录"
./ex17 $DB_FILE f "alice"

echo "8. 查找包含 'bob' 的记录"
./ex17 $DB_FILE f "bob"

echo "9. 删除记录 1"
./ex17 $DB_FILE d 1

echo "10. 再次列出所有记录（Bob应该被删除）"
./ex17 $DB_FILE l

echo "11. 尝试获取已删除的记录（应该失败）"
./ex17 $DB_FILE g 1 || echo "   ✓ 正确报错"

echo "12. 尝试设置超出范围的记录（应该失败）"
./ex17 $DB_FILE s 200 "Test" "test@test.com" || echo "   ✓ 正确报错"

echo "13. 尝试无效的操作（应该失败）"
./ex17 $DB_FILE x || echo "   ✓ 正确报错"

echo "14. 测试参数不足的情况（应该失败）"
./ex17 $DB_FILE || echo "   ✓ 正确报错"

echo "15. 测试查找不存在的字符串（应该无输出）"
./ex17 $DB_FILE f "nonexistent"

echo "16. 测试查找空字符串（应该列出所有记录）"
./ex17 $DB_FILE f ""

echo "=== 所有测试完成 ==="